-- Description: Current portable Chess content_source seed; generated by refresh_seeds.py.
-- Purpose: Refresh desired data without deleting omitted records.
-- Usage: Managed plugin deployment; refresh with tools/refresh_seeds.py.
--changeset clive:orac_chess_content_source_catalogue_2026_11_14 context:plugin,prod labels:plugin runOnChange:true stripComments:false endDelimiter:/
declare
  l_payload clob;

  procedure append_payload(p_hex varchar2) is
    l_text varchar2(32767);
  begin
    l_text := utl_i18n.raw_to_char(hextoraw(p_hex),'AL32UTF8');
    dbms_lob.writeappend(l_payload,length2(l_text),l_text);
  end;
begin
  dbms_lob.createtemporary(l_payload,true);
  append_payload('');
  append_payload('');
  for r in (select * from json_table(l_payload,'$[*]' columns (
    creator varchar2(1200) path '$.creator', author varchar2(1200) path '$.author',
    notes clob path '$.notes' null on empty))) loop
    merge into orac_chess.chess_content_source t
    using (select r.creator creator, r.author author,r.notes notes from dual) s
    on (t.creator=s.creator)
    when matched then update set t.updated_on=systimestamp,t.row_version=t.row_version+1,t.author=s.author, t.notes=s.notes
      where decode(t.author,s.author,0,1)=1 or (t.notes is null and s.notes is not null)
        or (t.notes is not null and s.notes is null)
        or dbms_lob.compare(t.notes,s.notes)<>0
    when not matched then insert (creator,author,notes)
      values (s.creator,s.author,s.notes);
  end loop;
  dbms_lob.freetemporary(l_payload);
exception when others then
  if dbms_lob.istemporary(l_payload)=1 then dbms_lob.freetemporary(l_payload); end if;
  raise;
end;
/
-- Retain reference data and user changes on rollback.
